"""Full video, step 1a: one complete keyframe per shot and orientation, generated by Codex (whole scene, no layers).

Usage: uv run python scripts/full_keys_codex.py <full_dir> [--workers 4] [--only s01,s02]
"""

from __future__ import annotations

import json
import sys
import time
from pathlib import Path

from sunomv.codex_images import ImageJob, generate_all

FRAMING = {
    "landscape": "Cinematic horizontal composition; keep the main subject and action inside the central 16:9 area.",
    "portrait": "Vertical composition for a phone screen; the main subject is centered and fills the frame.",
}


def shot_prompt(sb: dict, shot: dict, orientation: str) -> str:
    who = f" The woman is {sb['heroine']}." if "woman" in shot["scene"] else ""
    return f"Scene: {shot['scene']}{who} {FRAMING[orientation]} Style: {sb['style']}."


def main() -> None:
    full = Path(sys.argv[1])
    workers = int(sys.argv[sys.argv.index("--workers") + 1]) if "--workers" in sys.argv else 4
    only = set(sys.argv[sys.argv.index("--only") + 1].split(",")) if "--only" in sys.argv else None
    sb = json.loads((full / "storyboard.json").read_text())
    cover, sheet = full / "codex" / "cover.jpeg", full / "codex" / "character_sheet.png"
    jobs = []
    for shot in sb["shots"]:
        if only and shot["id"] not in only:
            continue
        refs = [cover, sheet] if "woman" in shot["scene"] else [cover]
        for orientation in ("landscape", "portrait"):
            out = full / "codex" / "keys" / f"{shot['id']}_{orientation}.png"
            jobs.append(ImageJob(out, shot_prompt(sb, shot, orientation), orientation, refs))
    started = time.monotonic()
    done = 0

    def report(job: ImageJob, result: float | str) -> None:
        nonlocal done
        done += 1
        print(f"[{done}/{len(jobs)}] {job.out.name}: {result} ({time.monotonic() - started:.0f}s elapsed)", flush=True)

    results = generate_all(jobs, workers=workers, on_done=report)
    (full / "codex" / "keys_report.json").write_text(json.dumps(results, indent=1))
    errors = [k for k, v in results.items() if isinstance(v, str)]
    print(f"done in {time.monotonic() - started:.0f}s, {len(errors)} errors: {errors}", flush=True)


if __name__ == "__main__":
    main()
